meta.input:
{
  "__tool_use_purpose": "Report approval to the engine",
  "command": "bun .kiro/tools/aidlc.ts engine orchestrate report --stage reverse-engineering --result approved --user-input \"Approve\""
}

{
  "__tool_use_purpose": "Get the next engine directive",
  "command": "bun .kiro/tools/aidlc-orchestrate.ts next"
}

{
  "operations": [
    {
      "mode": "Line",
      "path": "<project-dir>/.kiro/aidlc-common/stages/inception/practices-discovery.md"
    }
  ]
}

{
  "__tool_use_purpose": "Find the answer-mode rules in the stage protocol",
  "command": "grep -n -i \"answer.mode\\|answer-mode\\|--answer-mode\" .kiro/aidlc-common/protocols/stage-protocol.md"
}

{
  "operations": [
    {
      "mode": "Line",
      "offset": 470,
      "limit": 140,
      "path": "<project-dir>/.kiro/aidlc-common/protocols/stage-protocol.md"
    },
    {
      "mode": "Line",
      "path": "<project-dir>/aidlc/spaces/default/intents/261102-due-dates/inception/practices-discovery/evidence.md"
    }
  ]
}

{
  "__tool_use_purpose": "Log the answer-mode question",
  "command": "bun .kiro/tools/aidlc.ts engine log decision --stage practices-discovery --decision \"How would you like to answer the questions?\" --options \"Guide me,I'll edit the file,Chat\""
}

{
  "__tool_use_purpose": "Record the answer mode inferred from the grouped chat reply",
  "command": "bun .kiro/tools/aidlc.ts engine log answer --stage practices-discovery --details 'Chat' --on-instruction 'Answered all six questions in one grouped chat reply (Q1..Q6)'"
}

{
  "__tool_use_purpose": "Log the six interview questions",
  "command": "bun .kiro/tools/aidlc.ts engine log decision --stage practices-discovery --decision \"Practices interview Q1-Q6 (merge flow, thin slice first, test order and coverage, Python and pytest, formatter/linter, firm rules)\" --options \"Q1 A/B/C/X,Q2 A/B/X,Q3 A/B/C/X,Q4 A/B/X,Q5 A/B/X,Q6 A-E/X multi\""
}

{
  "__tool_use_purpose": "Record all six answers in one receipt",
  "command": "bun .kiro/tools/aidlc.ts engine log answer --stage practices-discovery --details 'Q1: Short-lived branches, squash-merged to `main`, one commit per piece of work, subject `<component>: <summary>`, no deploy step beyond the merge (suggested) | Q2: No -- the app already runs end to end (suggested) | Q3: Write the code, then its pytest tests; skip the 80% coverage and CI rule for this small CLI; the whole suite must pass before merge (suggested) | Q4: Require Python 3.10+, install pytest in a local virtual env, and prove changes with `python -m pytest` from the repo root (suggested) | Q5: No tool for now; follow PEP 8 by habit (suggested) | Q6: Old `tasks.json` files (no due date) must always still load'"
}

{
  "__tool_use_purpose": "Fill the answer tags in the questions file",
  "command": "bun -e 'const f=\"aidlc/spaces/default/intents/261102-due-dates/inception/practices-discovery/practices-discovery-questions.md\";const fs=require(\"fs\");let t=fs.readFileSync(f,\"utf8\");const a=[\"A\",\"A\",\"A\",\"A\",\"A\",\"A\"];let i=0;t=t.replace(/\\[Answer\\]:\\s*$/gm,()=>\"[Answer]: \"+a[i++]);fs.writeFileSync(f,t);console.log(i)'"
}

{
  "__tool_use_purpose": "Record all six interview answers in one receipt",
  "command": "bun .kiro/tools/aidlc.ts engine log answer --stage practices-discovery --details 'Q1: A, Q2: A, Q3: A, Q4: A, Q5: A, Q6: A (Q1 short-lived branches squash-merged to main, <component>: <summary> subjects, no deploy beyond merge; Q2 no thin slice first; Q3 code then pytest tests, no 80% coverage/CI rule, whole suite green before merge; Q4 Python 3.10+, pytest in local venv, verify with python -m pytest; Q5 no formatter/linter, PEP 8 by habit; Q6 firm rule: old tasks.json files without a due date must always still load)'"
}

{
  "__tool_use_purpose": "Emit PRACTICES_DISCOVERED",
  "command": "bun .kiro/tools/aidlc.ts engine state practices-event --type discovered --field \"Sources Scanned: git history, workspace config, codekb (code-structure, technology-stack, dependencies, code-quality-assessment, architecture, business-overview)\" --field \"Drafts: team-practices.md, discovered-rules.md\""
}

{
  "__tool_use_purpose": "Get timestamp for the diary",
  "command": "bun .kiro/tools/aidlc.ts engine now"
}

{
  "__tool_use_purpose": "Surface learning candidates",
  "command": "bun .kiro/tools/aidlc.ts engine learnings surface --slug practices-discovery"
}

{
  "__tool_use_purpose": "Log the keep-notes question",
  "command": "bun .kiro/tools/aidlc.ts engine log decision --stage practices-discovery --decision \"Which notes should be kept for next time?\" --options \"Keep none of these,Recorded the answer mode as Chat because the reply answered all six questions directly without picking a mode\""
}

{
  "__tool_use_purpose": "Log the anything-to-add question",
  "command": "bun .kiro/tools/aidlc.ts engine log decision --stage practices-discovery --decision \"Anything to add for next time?\" --options \"Nothing to add,Add a note\""
}
